// @ts-check
// Plain CommonJS so Expo's config loader can require it from app.config.ts's
// plugins list without compiling TypeScript.
const { withAppBuildGradle } = require("expo/config-plugins");

// Signs release builds with the household keystore. android/ is generated by
// prebuild (CNG), so the signing config is injected here rather than committed.
// Gradle reads the keystore path and passwords from the environment at build
// time, so no secret is ever written into the generated build.gradle.

/** The variables Gradle reads at build time; never written into the file. */
const SIGNING_ENV = Object.freeze([
  "CHOTU_ANDROID_KEYSTORE_PATH",
  "CHOTU_ANDROID_KEYSTORE_PASSWORD",
  "CHOTU_ANDROID_KEY_ALIAS",
  "CHOTU_ANDROID_KEY_PASSWORD",
]);

const MARKER = "// @generated chotu-release-signing";

const SIGNING_CONFIG = `
        release { ${MARKER}
            def chotuKeystorePath = System.getenv("CHOTU_ANDROID_KEYSTORE_PATH")
            if (chotuKeystorePath) {
                storeFile file(chotuKeystorePath)
                storePassword System.getenv("CHOTU_ANDROID_KEYSTORE_PASSWORD")
                keyAlias System.getenv("CHOTU_ANDROID_KEY_ALIAS")
                keyPassword System.getenv("CHOTU_ANDROID_KEY_PASSWORD")
            }
        }`;

// Without this guard, missing variables would quietly produce an unsigned APK.
// Checked only when a release task is about to run, so debug builds need no keystore.
const RELEASE_GUARD = `
${MARKER}
// A release build must be signed with the Chotu keystore, never the debug key.
gradle.taskGraph.whenReady { graph ->
    def releaseTasks = graph.allTasks.findAll { it.project == project && it.name.contains("Release") }
    if (releaseTasks.isEmpty()) {
        return
    }
    def required = [${SIGNING_ENV.map((name) => `"${name}"`).join(", ")}]
    def missing = required.findAll { !System.getenv(it) }
    if (!missing.isEmpty()) {
        throw new GradleException("Release signing is not configured. Set " + missing.join(", ") + " (see docs/app.md).")
    }
    def keystore = file(System.getenv("CHOTU_ANDROID_KEYSTORE_PATH"))
    if (!keystore.isFile()) {
        throw new GradleException("Release keystore not found: " + keystore + " (see docs/app.md).")
    }
}
`;

const SIGNING_CONFIGS_ANCHOR = /signingConfigs\s*\{/;
const RELEASE_SIGNING_LINE =
  /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;

/**
 * Adds the release signing config and the release guard to
 * android/app/build.gradle. Running it again leaves the file unchanged.
 *
 * @param {string} buildGradle
 * @returns {string}
 */
function addReleaseSigning(buildGradle) {
  if (buildGradle.includes(MARKER)) {
    return buildGradle;
  }
  if (!SIGNING_CONFIGS_ANCHOR.test(buildGradle) || !RELEASE_SIGNING_LINE.test(buildGradle)) {
    throw new Error(
      "with-release-signing: android/app/build.gradle no longer matches the expected template. Update app/plugins/with-release-signing.js.",
    );
  }
  const withConfig = buildGradle.replace(
    SIGNING_CONFIGS_ANCHOR,
    (anchor) => `${anchor}${SIGNING_CONFIG}`,
  );
  const withRelease = withConfig.replace(
    RELEASE_SIGNING_LINE,
    "$1signingConfig signingConfigs.release",
  );
  return `${withRelease.trimEnd()}\n${RELEASE_GUARD}`;
}

/** @type {import("expo/config-plugins").ConfigPlugin} */
const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (modConfig) => {
    if (modConfig.modResults.language !== "groovy") {
      throw new Error("with-release-signing: expected a Groovy android/app/build.gradle.");
    }
    modConfig.modResults.contents = addReleaseSigning(modConfig.modResults.contents);
    return modConfig;
  });

// The plugin is the default export, for app.config.ts's plugins list; the
// helpers ride along for the tests.
module.exports = Object.assign(withReleaseSigning, { addReleaseSigning, SIGNING_ENV });
